TIMEOUT = object()  # sentinel returned when a scenario exceeds its time budget


def run_scenario(coro_factory, budget=8.0):
    """Run an async scenario under a wall-clock budget.

    Returns the scenario's result, or the ``TIMEOUT`` sentinel if it did not
    finish in ``budget`` seconds. This keeps the verifier from hanging forever
    on a broken artifact (e.g. one that serializes work so a blocked task never
    yields to the task that is supposed to interrupt the run).
    """

    async def _wrapped():
        try:
            return await asyncio.wait_for(coro_factory(), timeout=budget)
        except asyncio.TimeoutError:
            return TIMEOUT

    return asyncio.run(_wrapped())

